import fs from 'node:fs';
const p='assets/css/site.css';
let css=fs.readFileSync(p,'utf8');
const oldClean='body.apple-archive.press-page .press-record .desc,body.apple-archive.press-page .press-record .note{grid-column:2;margin:0;max-width:none;color:#BED0E2}\nbody.apple-archive.press-page .press-record .note{font-size:.82rem;color:#AFC4D9}';
const newClean='body.apple-archive.press-page .press-record .desc,body.apple-archive.press-page .press-record .note{grid-column:2;margin:0;max-width:none}\nbody.apple-archive.press-page .press-record .desc{color:#F5F5F7!important;opacity:1!important}\nbody.apple-archive.press-page .press-record .note{font-size:.82rem;color:#AFC4D9}';
if(!css.includes(oldClean)) throw new Error('ART clean press rule not found');
css=css.replace(oldClean,newClean);
const oldMuseum='html body.apple-archive section.era .grid article.item p.desc{color:var(--mus-soft)!important;max-width:54ch!important}';
const newMuseum='html body.apple-archive section.era .grid article.item p.desc{color:#F5F5F7!important;opacity:1!important;max-width:54ch!important}';
if(!css.includes(oldMuseum)) throw new Error('ART museum press desc rule not found');
css=css.replace(oldMuseum,newMuseum);
fs.writeFileSync(p,css,'utf8');
console.log('ART press description contrast corrected in the single source CSS authority.');
